package com.aliothmoon.maafw.once;
import org.junit.Test;import static org.junit.Assert.*;import java.nio.file.Path;
public class ReadOnlyCheckpointTest {
 @Test public void onlyOneImmutableCompiledPolicy(){assertEquals(12,ReadOnlyCheckpoint.values().length);assertSame(ReadOnlyCheckpoint.UI_BOUND_POINTS_V53,ReadOnlyCheckpoint.CURRENT);assertEquals(1794466200000L,ReadOnlyCheckpoint.PROGRESS_LAYOUT_V41.starts());assertEquals(1794474000000L,ReadOnlyCheckpoint.PROGRESS_LAYOUT_V41.expires());assertEquals(-1,ReadOnlyCheckpoint.CURRENT.sourceTask());}
 @Test public void slotRejectsZeroTwoAndNullStorage(){var p=ReadOnlyCheckpoint.CURRENT;assertTrue(p.validIndex(1));assertFalse(p.validIndex(0));assertFalse(p.validIndex(2));assertThrows(SecurityException.class,()->p.store(null,1));assertThrows(SecurityException.class,()->p.store(Path.of("fixture"),2));}
 @Test public void admissionCannotExtendPastAbsoluteWindow(){var p=ReadOnlyCheckpoint.CURRENT;assertTrue(p.admissionCurrent(p.starts()));assertFalse(p.admissionCurrent(p.expires()-ReadOnlyCheckpoint.SESSION_TTL));assertFalse(p.current(p.expires()));assertThrows(SecurityException.class,()->p.sessionDeadline(1000,p.expires()));}
 @Test public void deadlinesAreBoundedByParentAndWallClock(){var p=ReadOnlyCheckpoint.CURRENT;assertEquals(181000,p.sessionDeadline(1000,p.starts()));assertEquals(91000,p.deadline(1000,p.starts(),181000));assertEquals(1500,p.deadline(1000,p.starts(),1500));assertEquals(1010,p.deadline(1000,p.expires()-10,5000));}
 @Test public void invalidTimeNeverOverflowsIntoAuthority(){var p=ReadOnlyCheckpoint.CURRENT;assertThrows(SecurityException.class,()->p.sessionDeadline(-1,p.starts()));assertThrows(SecurityException.class,()->p.sessionDeadline(Long.MAX_VALUE,p.starts()));assertThrows(SecurityException.class,()->p.deadline(Long.MAX_VALUE,p.starts(),Long.MAX_VALUE));assertThrows(SecurityException.class,()->p.deadline(1000,p.starts(),1000));}
 @Test public void v45DoesNotExtendOrReuseV44(){var old=ReadOnlyCheckpoint.UI_STRUCTURE_V44;var now=ReadOnlyCheckpoint.UI_STRUCTURE_V45;assertEquals(1794472380000L,old.starts());assertEquals(1794474000000L,old.expires());assertEquals("rewards-ui-progress-20261112-v44",old.directory());assertEquals(1794474000000L,now.starts());assertEquals(1794477600000L,now.expires());assertNotEquals(old.directory(),now.directory());assertFalse(now.admissionCurrent(1794477420000L));}
}
